-------------------------------------;ConvertRead;; Read the resource from disk, relocate it, dispose; of old handle, put new handle into resref record.;;-----------------------------------------------------------;; Read the data into memory;	pei ConvertParam+2	pei ConvertParam	PushWord #$2012	jsl $E100B0	bcc @continue	rts@continue;; Lets find the userid of the current memory.;	ldy #ResRefRecord.ResHandle	lda [ResPointer],y	sta result	iny	iny	lda [ResPointer],y	sta result+2	ldy #6	lda [Result],y	tay	; put result in y for now.	stz Result	; fix this again.	stz Result+2;; Relocate it;	pha	; space for user id	pha	; space for starting addr	pha	pha	; space for d-page/stack	pha	; size of d-page/stack	phy	; push the desired userid	lda convertParam	; point to a packett that has pointer followed by 	clc	; size	adc #4	tax	lda convertParam+2	adc #0	pha	phx	PushWord #0	; don't use special memory	PushWord #4	; input type for mem to mem that stays out of loader table	_InitialLoad2	bcs @LoadError	pla	; ignore user id	pla	; this is pointer to reloced code	plx	ply	; ignore size of direct page buffer	ply	; ignore addr of direct page buffer;; Find the handle to the relocated code and leave result on stack.;	pha	; space for handle	pha	phx	; save pointer to relocated code on the stack.	pha	_FindHandle	bcs @FindError;; dispose of old handle;	ldy #resRefRecord.resHandle+2	lda [ResPointer],y	pha	dey	dey	lda [ResPointer],y	pha	_DisposeHandle;; Put new handle into resource map;	ldy #resRefRecord.resHandle	pla	sta [ResPointer],y	iny	iny	pla	sta [ResPointer],y	lda #0	clc	rts@LoadError	plx	plx	plx@FindError	plx	plx	rts;-----------------------------------------------------------;ConvertWrite;; Writes the resource to disk.;;-----------------------------------------------------------;; Write the data to disk;	pei ConvertParam+2	pei ConvertParam	PushWord #$2013	jsl $E100B0	rts;-----------------------------------------------------------;ConvertDiskSize;; Returns the size the resource will take on disk.;;-----------------------------------------------------------;; Return the size of the handle in the ResRef record.;	pha	pha	ldy #ResRefRecord.ResHandle+2	lda [ResPointer],y	pha	dey	dey	lda [ResPointer],y	pha	_GetHandleSize;; return the result;	plx	stx Result	plx	stx Result+2	rts	ENDP	END